import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"Customer booking gateway","description":"","frontmatter":{},"headers":[],"relativePath":"plus/customer-booking-gateway.md","filePath":"plus/customer-booking-gateway.md"}'),n={name:"plus/customer-booking-gateway.md"};function r(s,e,c,l,d,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="customer-booking-gateway" tabindex="-1">Customer booking gateway <a class="header-anchor" href="#customer-booking-gateway" aria-label="Permalink to &quot;Customer booking gateway&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="activation-boundary" tabindex="-1">Activation boundary <a class="header-anchor" href="#activation-boundary" aria-label="Permalink to &quot;Activation boundary&quot;">​</a></h2><p>The separate guest gateway is implemented with independent public catalog, quote, request and lookup gates. Public intake remains disabled pending authorization. The storefront must never embed operator tokens or have unrestricted database access.</p><h2 id="approved-customer-journey" tabindex="-1">Approved customer journey <a class="header-anchor" href="#approved-customer-journey" aria-label="Permalink to &quot;Approved customer journey&quot;">​</a></h2><ol><li>Confirm the company&#39;s approved publication channel and catalog. Only published locations, services and vehicle options should be offered.</li><li>The customer selects a route, date/time, passengers, luggage and service details. Validate the applicable service and capacity. The server returns a verified positive tariff or a manual quotation requirement; do not invent a zero fare.</li><li>Provide the passenger&#39;s name and telephone; email is optional. Do not fabricate an address for phone-only bookings.</li><li>Review the current quote and submit once using the approved customer gateway. The server checks signed quotation context and duplicate/concurrent submission protections. An expired or changed quote requires fresh review.</li><li>Review the returned booking reference and status. A request is not a completed payment or automatic dispatch authorization. The operator checks pending quotes, CRM matching and the resulting reservation before confirmation/dispatch.</li></ol><h2 id="acceptance-before-publication" tabindex="-1">Acceptance before publication <a class="header-anchor" href="#acceptance-before-publication" aria-label="Permalink to &quot;Acceptance before publication&quot;">​</a></h2><p>Verify tenant and channel isolation, restricted database access, abuse protection, quote tampering rejection, duplicate submissions, safe CRM linkage, optional email, passenger-safe lookup and disabled-feature behavior. Use isolated synthetic data and separate authorization for payment and notification providers. Do not publish until the approved live acceptance and commercial activation gates are met.</p><p>See <a href="/plus/create-reservation.html">Create a reservation</a>, <a href="/plus/passenger-information.html">Passenger information</a> and <a href="/integrations/third-party-api-setup.html">API setup</a>.</p>',9)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
